from flask import Flask, session, request, jsonify

app = Flask(__name__)
app.secret_key = 'your-secret-key'  # 用于会话的密钥

@app.route('/info', methods=['GET'])
def info():
    # 检查会话中是否存在用户名、邮箱和SSN
    username = session.get('username')
    email = session.get('email')
    ssn = session.get('ssn')

    if username is None or email is None or ssn is None:
        return jsonify({"error": "Session data not found. Please log in first."}), 400

    # 返回包含用户名、邮箱和SSN的字符串
    return jsonify({
        "username": username,
        "email": email,
        "ssn": ssn
    })

if __name__ == '__main__':
    app.run(debug=True)

