def validate_user_input(name, email, ssn):
    if not name or not email or not ssn:
        return False
    if len(name.strip()) < 2:
        return False
    if '@' not in email or '.' not in email:
        return False
    if not ssn.replace('-', '').isdigit() or len(ssn.replace('-', '')) != 9:
        return False
    return True
